      "achados": [
        {
          "proposicao": "No reator eletrostático descrito, diferentes regiões de eletrodos são usadas para combinar dispersão e coalescência: uma região de bocal com componente vertical de campo para dispersar e acelerar a fase dispersa, e um canal operacional com placas paralelas e sinal elétrico modulado para controlar residência e promover ciclos de coalescência e redispersão.",
          "trechos": [
            "E2b5eecde6a4c0711:690:1387",
            "E2b5eecde6a4c0711:1387:2087"
          ],
          "condicoes": [
            "configuração específica de contactor/reactor EPC desenvolvida no Oak Ridge National Laboratory",
            "fase mais densa dispersa na fase contínua"
          ],
          "limites": [
            "o equipamento descrito não é identificado como tratador eletrostático de petróleo em FPSO",
            "não há descrição de alarmes, intertravamentos, curtos, arcos, isoladores ou transformadores",
            "o arranjo experimental não deve ser generalizado como arquitetura padrão de tratadores"
          ]
        },
        {
          "proposicao": "A fonte atribui ao campo elétrico na base do reator a aceleração de gotas aquosas em direção à interface orgânico-aquosa, com aumento da coalescência e da separação na interface.",
          "trechos": [
            "E2b5eecde6a4c0711:1387:2087"
          ],
          "condicoes": [
            "existência de placa central eletrificada e fase aquosa aterrada",
            "presença de interface orgânico-aquosa no equipamento"
          ],
          "limites": [
            "é descrição de mecanismo em configuração experimental/comercial distinta do recorte FPSO",
            "não informa instabilidade de campo nem proteção contra falhas"
          ]
        },
        {
          "proposicao": "A fonte relata operação comercial prolongada de dessalgadores eletrostáticos de petróleo e compara consumo energético volumétrico do sistema EPC com sistemas mecânicos para geração de emulsões finas, caracterizando evidência empírica de desempenho de uma tecnologia específica.",
          "trechos": [
            "E2b5eecde6a4c0711:0:690",
            "E2b5eecde6a4c0711:1387:2087"
          ],
          "condicoes": [
            "comparação feita no contexto do sistema e fluidos citados no trecho"
          ],
          "limites": [
            "os valores numéricos aparecem suprimidos e não podem ser reconstruídos",
            "a comparação não estabelece regra universal para tratadores de petróleo",
            "não conecta consumo energético a critérios de proteção elétrica"
          ]
        }
      ]
